import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import { createText as _unused } from '@/text'; // ensures alias is resolved, not used directly

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, MathUtils, Color, DirectionalLight, PointLight } = ctx.THREE;

  // Root group
  const root = new Group();
  root.name = 'FilmstripCarousel';

  // ---------- Backdrop Gradient ----------
  const bgGeom = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial({
    colorNode: mix(color('#0b0b10'), color('#12121a'), uv().y)
  });
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  // ---------- Text Elements ----------
  const headline = ctx.fontAtlas.createText('The collection', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left'
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);

  const body = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left'
  });
  body.position.set(-2.6, -1.5, 0);
  root.add(body);

  // ---------- Card Strip ----------
  const stripGroup = new Group();
  stripGroup.rotation.y = MathUtils.degToRad(-18);
  root.add(stripGroup);

  // Geometry shared among cards
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const bevelSize = 0.025;
  const cardGeom = new PlaneGeometry(cardWidth, cardHeight);
  const frameGeom = new PlaneGeometry(cardWidth + bevelSize * 2, cardHeight + bevelSize * 2);

  // Underline geometry (for focused card)
  const underlineGeom = new PlaneGeometry(cardWidth, 0.035);

  // Load texture once
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Caption strings (order corresponds to card index)
  const captionStrings = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE'
  ];

  // Opacity map based on distance from center index (2)
  const opacityMap = [0.55, 0.80, 1.0, 0.80, 0.55];
  const scaleFocused = 1.0;
  const scaleSide = 0.92;

  const cardMaterials = [];
  const frameMaterials = [];
  const underlineMaterial = (() => {
    const mat = new MeshStandardNodeMaterial({
      color: new Color('#ff2a38'),
      emissive: new Color('#ff2a38'),
      emissiveIntensity: 1.3,
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      side: THREE.DoubleSide
    });
    return mat;
  })();

  for (let i = 0; i < 5; i++) {
    const isFocused = i === 2;

    // Card material
    const cardMat = new MeshStandardNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true,
      opacity: opacityMap[i],
      side: THREE.DoubleSide
    });
    cardMaterials.push(cardMat);

    // Frame material (ink bevel)
    const frameMat = new MeshStandardNodeMaterial({
      color: new Color('#16161d'),
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      side: THREE.DoubleSide
    });
    frameMaterials.push(frameMat);

    // Group for this card
    const cardGroup = new Group();
    cardGroup.position.set((i - 2) * 1.85, 0, 0);
    cardGroup.scale.setScalar(isFocused ? scaleFocused : scaleSide);
    stripGroup.add(cardGroup);

    // Frame mesh (behind card)
    const frameMesh = new Mesh(frameGeom, frameMat);
    frameMesh.position.z = -0.001;
    cardGroup.add(frameMesh);

    // Card mesh
    const cardMesh = new Mesh(cardGeom, cardMat);
    cardMesh.position.z = 0.001;
    cardGroup.add(cardMesh);

    // Underline for focused card
    if (isFocused) {
      const underline = new Mesh(underlineGeom, underlineMaterial);
      underline.position.set(0, -cardHeight / 2 - 0.035 / 2 - 0.02, 0.002);
      cardGroup.add(underline);
    }

    // Caption text
    const caption = ctx.fontAtlas.createText(captionStrings[i], {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
      letterSpacing: 0.08
    });
    caption.position.set(0, -cardHeight / 2 - 0.035 - 0.07, 0);
    cardGroup.add(caption);
  }

  // Apply texture when loaded
  texturePromise.then((tex) => {
    cardMaterials.forEach((mat) => {
      mat.map = tex;
      mat.needsUpdate = true;
    });
  });

  // ---------- Lighting ----------
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(0, 2, 2);
  root.add(keyLight);

  const rimLight = new PointLight('#ff2a38', 0.6);
  rimLight.position.set(-1, 0, 2);
  root.add(rimLight);

  // ---------- Cinematic Primitive ----------
  const primitive = ctx.primitives['parallax-scroll'](stripGroup, { intensity: 0.5 });

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometries
    bgGeom.dispose();
    cardGeom.dispose();
    frameGeom.dispose();
    underlineGeom.dispose();

    // Dispose materials
    bgMat.dispose();
    underlineMaterial.dispose();
    cardMaterials.forEach((m) => m.dispose());
    frameMaterials.forEach((m) => m.dispose());

    // Dispose texture if loaded
    texturePromise.then((tex) => {
      tex.dispose();
    });

    // Primitive cleanup
    if (primitive && typeof primitive.cleanup === 'function') {
      primitive.cleanup();
    }

    // Kill GSAP timelines (none used directly, but defensive)
    gsap.globalTimeline.clear();
  };

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  return root;
}
